import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport '../../auth/providers/auth_providers.dart';\nimport '../../auth/views/onboarding_screen.dart';\nimport 'add_homework_screen.dart';\nimport 'add_announcement_screen.dart';\nimport 'manage_schedule_screen.dart';\n// import 'manage_comments_screen.dart';\n\nclass TeacherDashboardScreen extends ConsumerWidget {\n  const TeacherDashboardScreen({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('لوحة تحكم المعلم'),\n        centerTitle: true,\n        actions: [\n          IconButton(\n            icon: const Icon(Icons.logout),\n            onPressed: () async {\n              await ref.read(authServiceProvider).logout();\n              if (!context.mounted) return;\n              Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const OnboardingScreen()));\n            },\n          )\n        ],\n      ),\n      body: GridView.count(\n        crossAxisCount: 2,\n        padding: const EdgeInsets.all(16),\n        crossAxisSpacing: 16,\n        mainAxisSpacing: 16,\n        children: [\n          _buildDashboardCard(\n            context,\n            icon: Icons.assignment_add,\n            title: 'إضافة تحضير',\n            color: Colors.blue,\n            onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const AddHomeworkScreen())),\n          ),\n          _buildDashboardCard(\n            context,\n            icon: Icons.campaign,\n            title: 'إضافة إعلان',\n            color: Colors.orange,\n            onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const AddAnnouncementScreen())),\n          ),\n          _buildDashboardCard(\n            context,\n            icon: Icons.calendar_month,\n            title: 'تعديل الجدول',\n            color: Colors.green,\n            onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const ManageScheduleScreen())),\n          ),\n          _buildDashboardCard(\n            context,\n            icon: Icons.comment,\n            title: 'إدارة التعليقات',\n            color: Colors.purple,\n            onTap: () {},\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildDashboardCard(BuildContext context, {required IconData icon, required String title, required Color color, required VoidCallback onTap}) {\n    return InkWell(\n      onTap: onTap,\n      child: Card(\n        elevation: 4,\n        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            Icon(icon, size: 60, color: color),\n            const SizedBox(height: 16),\n            Text(title, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),\n          ],\n        ),\n      ),\n    );\n  }\n}\n